const inventionsData=[{id:"pingala-binary",name:"Pingala's Binary System",inventor:"Pingala",year:"-200",category:"mathematics",desc:"The first known description of a binary numeral system, used for poetic meters in Chandas Shastra.",img:"https://placehold.co/400x300/064e3b/fff",link:"../pingala-binary-concepts/index.html",featured:!0},{id:"sushruta-surgery",name:"Plastic Surgery & Rhinoplasty",inventor:"Sushruta",year:"-600",category:"medicine",desc:"Sushruta Samhita details over 300 surgical procedures and the use of 120 surgical instruments.",img:"https://placehold.co/400x300/991b1b/fff",featured:!0},{id:"zinc-smelting",name:"Zinc Smelting",inventor:"Zawar Miners",year:"1200",category:"metallurgy",desc:"India was the first to smelt zinc on an industrial scale using the downward distillation technique.",img:"https://placehold.co/400x300/475569/fff",featured:!0},{id:"stepwell",name:"Stepwell Architecture (Vav)",inventor:"Ancient Engineers",year:"550",category:"architecture",desc:"Ingenious water harvesting structures that served as community hubs and cool retreats in arid regions.",img:"https://placehold.co/400x300/b45309/fff",featured:!1},{id:"chess",name:"Chaturanga (Chess)",inventor:"Gupta Empire",year:"500",category:"games",desc:"The precursor to modern chess, simulating ancient Indian military strategy with infantry, cavalry, and elephants.",img:"https://placehold.co/400x300/1e3a8a/fff",featured:!1},{id:"cotton-cultivation",name:"Cotton Cultivation & Weaving",inventor:"Indus Valley",year:"-3000",category:"textiles",desc:"The first civilization to cultivate and weave cotton, exporting fine muslin to the ancient world.",img:"https://placehold.co/400x300/15803d/fff",featured:!1},{id:"aryabhata-zero",name:"Place Value System & Zero",inventor:"Aryabhata / Brahmagupta",year:"499",category:"mathematics",desc:"The conceptualization of zero as a number and the decimal place-value system that revolutionized math.",img:"https://placehold.co/400x300/064e3b/fff",featured:!0},{id:"seamless-globe",name:"Seamless Celestial Globe",inventor:"Ali Kashmiri",year:"1584",category:"astronomy",desc:"A metallurgical marvel cast in a single piece without any seams, considered impossible by modern foundries until rediscovered.",img:"https://placehold.co/400x300/475569/fff",featured:!1}],timelineEras=[{era:"3000 BCE",desc:"Indus Valley urban planning, cotton cultivation, and early metallurgy."},{era:"600 BCE",desc:"Sushruta pioneers surgery; early texts on astronomy and mathematics emerge."},{era:"200 BCE",desc:"Pingala documents binary patterns; Panini formalizes Sanskrit grammar."},{era:"500 CE",desc:"The Golden Age: Aryabhata calculates pi, invents place-value, and Chaturanga is born."},{era:"1200 CE",desc:"Zinc smelting reaches industrial scale in Rajasthan; stepwell architecture peaks."},{era:"1600 CE",desc:"Mughal era metallurgy produces seamless celestial globes and Wootz steel."}];let observer,currentCategory="all",searchTerm="";function init(){renderTimeline(),renderInventions(),attachEventListeners(),setupThemeToggle(),setupScrollAnimations()}function renderTimeline(){const e=document.getElementById("timeline-scroller");e&&(e.innerHTML=timelineEras.map(e=>`\n        <div class="timeline-node">\n            <div class="timeline-era">${e.era}</div>\n            <div class="timeline-desc">${e.desc}</div>\n        </div>\n    `).join(""))}function renderInventions(){const e=document.getElementById("invention-grid");if(!e)return;const t=inventionsData.filter(e=>{const t="all"===currentCategory||e.category===currentCategory,n=e.name.toLowerCase().includes(searchTerm.toLowerCase())||e.inventor.toLowerCase().includes(searchTerm.toLowerCase())||e.desc.toLowerCase().includes(searchTerm.toLowerCase());return t&&n});0!==t.length?(e.innerHTML=t.map(e=>`\n        <div class="invention-card animate-on-scroll" role="listitem" tabindex="0" ${e.link?`onclick="window.location.href='${e.link}'"`:""}>\n            <div class="card-img" style="background-image: url('${e.img}')">\n                <span class="card-category">${e.category}</span>\n            </div>\n            <div class="card-content">\n                <h3>${e.name}</h3>\n                <div class="card-inventor">${e.inventor}</div>\n                <p>${e.desc}</p>\n                <div class="card-footer">\n                    <span>Est. ${e.year>0?e.year+" CE":Math.abs(e.year)+" BCE"}</span>\n                    ${e.featured?'<span style="color: var(--accent); font-weight: 600;">⭐ Featured</span>':""}\n                </div>\n            </div>\n        </div>\n    `).join(""),observer&&document.querySelectorAll(".invention-card").forEach(e=>observer.observe(e))):e.innerHTML='<p style="grid-column: 1/-1; text-align: center; color: var(--text-secondary);">No inventions found matching your criteria.</p>'}function attachEventListeners(){document.querySelectorAll(".filter-btn").forEach(e=>{e.addEventListener("click",()=>{document.querySelectorAll(".filter-btn").forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),e.classList.add("active"),e.setAttribute("aria-selected","true"),currentCategory=e.dataset.category,renderInventions()})});const e=document.getElementById("invention-search");e&&e.addEventListener("input",debounce(e=>{searchTerm=e.target.value,renderInventions()},300))}function setupThemeToggle(){const e=document.getElementById("theme-toggle");e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const t=document.body.classList.contains("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"☀️":"🌙"}),"light"===localStorage.getItem("theme")&&(document.body.classList.add("light-theme"),e.textContent="☀️")}function setupScrollAnimations(){"IntersectionObserver"in window&&(observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.1}),document.querySelectorAll(".animate-on-scroll").forEach(e=>observer.observe(e)))}function debounce(e,t){let n;return function(...a){clearTimeout(n),n=setTimeout(()=>e.apply(this,a),t)}}document.addEventListener("DOMContentLoaded",init);